/* USE : NaverOrderLinkMapper.getApiUrl */
SELECT  FN_GET_API_URL(#{storeCd}, #{apiInfo}, #{apiUrl}) AS ${apiUrl}
,       FN_GET_API_URL(#{storeCd}, #{apiInfo}, #{apiKey}) AS ${apiKey}
FROM    DUAL

 /* NaverOrderLinkMapper.getNaverUniqueId */
SELECT  ORDER_UNIQUE_ID AS UNIQUE_ID
FROM    TB_CM_NAVER_LINK
WHERE   HQ_OFFICE_CD = #{hqOfficeCd}
AND     STORE_CD     = #{storeCd}

mapper.update:
/* NaverOrderLinkMapper.saveNaverAgreement */
MERGE INTO TB_CM_NAVER_LINK_AGREEMENT A
USING DUAL
ON (
        A.HQ_OFFICE_CD = #{hqOfficeCd}
    AND A.STORE_CD     = #{storeCd}
)
WHEN MATCHED THEN
UPDATE
   SET A.UNIQUE_ID         = #{uniqueId}
,      A.LAST_RESPONSE_DT  = #{lastResponseDt}
,      A.AGREEMENT_TYPE    = #{agreementType}
,      A.MOD_DT            = #{modDt}
,      A.MOD_ID            = #{modId}
WHEN NOT MATCHED THEN
INSERT (
    A.HQ_OFFICE_CD
,   A.STORE_CD
,   A.UNIQUE_ID
,   A.LAST_RESPONSE_DT
,   A.AGREEMENT_TYPE
,   A.REG_DT
,   A.REG_ID
,   A.MOD_DT
,   A.MOD_ID
)
VALUES (
    #{hqOfficeCd}
,   #{storeCd}
,   #{uniqueId}
,   #{lastResponseDt}
,   #{agreementType}
,   #{regDt}
,   #{regId}
,   #{modDt}
,   #{modId}
)

/* USE : NaverOrderLinkMapper.saveNaverOrderLink */
UPDATE TB_CM_NAVER_LINK
SET    ORDER_BUSINESS_ID = #{orderBusinessId}
,      ORDER_CHANNEL_SERVICE_ID_TABLE = #{orderChannelServiceIdTable}
,      ORDER_CHANNEL_SERVICE_ID_PICKUP = #{orderChannelServiceIdPickup}
,      MOD_DT = #{modDt}
,      MOD_ID = #{modId}
WHERE  HQ_OFFICE_CD = #{hqOfficeCd}
AND    STORE_CD = #{storeCd}

